"""Intent tests for risk.rolling_vol (M1-T09): TC-05 and RISK-02."""

from __future__ import annotations

import pytest
from hypothesis import given
from hypothesis import strategies as st

from risk.types import Returns, VolSeries
from risk.vol import rolling_vol


def _returns(payload: dict) -> Returns:
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={t: tuple(v) for t, v in payload["values"].items()},
    )


@pytest.mark.intent
def test_tc05_rolling_vol_matches_expected(golden):
    given_input, expected = golden("risk", "TC-05")
    returns = _returns(given_input["returns"])

    vol = rolling_vol(returns, given_input["window"])

    assert isinstance(vol, VolSeries)
    assert vol.window == expected["window"]
    assert vol.annualized is expected["annualized"]
    assert vol.returns == returns
    assert set(vol.values) == set(expected["values"])
    for ticker, want in expected["values"].items():
        got = vol.values[ticker]
        assert len(got) == len(returns.dates)
        for g, w in zip(got, want, strict=True):
            if w is None:
                assert g is None
            else:
                assert g == pytest.approx(w, abs=expected["tol"])


@pytest.mark.intent
def test_tc05_no_value_until_window_earlier_returns(golden):
    given_input, _ = golden("risk", "TC-05")
    returns = _returns(given_input["returns"])
    window = given_input["window"]

    vol = rolling_vol(returns, window)

    for ticker in returns.tickers:
        assert all(v is None for v in vol.values[ticker][:window])
        assert all(v is not None for v in vol.values[ticker][window:])


@pytest.mark.intent
@pytest.mark.parametrize("window", [1, 0, -3])
def test_window_below_two_is_value_error(contract_sample, window):
    returns = _returns(contract_sample("risk.Returns"))

    with pytest.raises(ValueError, match="window"):
        rolling_vol(returns, window)


@pytest.mark.intent
@given(last=st.floats(min_value=-0.5, max_value=0.5, allow_nan=False))
def test_vol_never_uses_the_dates_own_return(last):
    base = {
        "base_date": "2024-01-02",
        "dates": ["2024-01-03", "2024-01-04", "2024-01-05", "2024-01-08", "2024-01-09"],
        "tickers": ["A"],
        "values": {"A": [0.01, -0.02, 0.015, 0.0, 0.03]},
    }
    changed = {**base, "values": {"A": [0.01, -0.02, 0.015, 0.0, last]}}

    vol_base = rolling_vol(_returns(base), 2)
    vol_changed = rolling_vol(_returns(changed), 2)

    assert vol_changed.values["A"] == vol_base.values["A"]

