"""Intent tests for risk.summary_stats (M1-T11): TC-07 and RISK-04."""

from __future__ import annotations

import pytest

from risk.summary import TickerSummary, summary_stats
from risk.types import Returns, VolSeries


def _returns(payload: dict) -> Returns:
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={t: tuple(v) for t, v in payload["values"].items()},
    )


def _vol(payload: dict) -> VolSeries:
    return VolSeries(
        returns=_returns(payload["returns"]),
        window=payload["window"],
        annualized=payload["annualized"],
        values={t: tuple(v) for t, v in payload["values"].items()},
    )


def _by_ticker(summaries: tuple[TickerSummary, ...]) -> dict[str, TickerSummary]:
    return {s.ticker: s for s in summaries}


@pytest.mark.intent
def test_tc07_summary_matches_expected(golden):
    given_input, expected = golden("risk", "TC-07")
    vol = _vol(given_input["vol"])

    got = summary_stats(vol)

    assert isinstance(got, tuple)
    assert all(isinstance(s, TickerSummary) for s in got)
    assert [s.ticker for s in got] == [w["ticker"] for w in expected["summary"]]
    by_ticker = _by_ticker(got)
    tol = expected["tol"]
    for want in expected["summary"]:
        s = by_ticker[want["ticker"]]
        assert s.ann_return == pytest.approx(want["ann_return"], abs=tol)
        assert s.ann_vol == pytest.approx(want["ann_vol"], abs=tol)
        assert s.sharpe == pytest.approx(want["sharpe"], abs=tol)
        assert s.last_vol == pytest.approx(want["last_vol"], abs=tol)


@pytest.mark.intent
def test_tc07_zero_volatility_gives_zero_sharpe(golden):
    given_input, expected = golden("risk", "TC-07")
    vol = _vol(given_input["vol"])
    want = next(w for w in expected["summary"] if w["ticker"] == "Y")

    s = _by_ticker(summary_stats(vol))["Y"]

    assert s.ann_vol == pytest.approx(want["ann_vol"], abs=expected["tol"])
    assert s.sharpe == pytest.approx(want["sharpe"], abs=expected["tol"])


@pytest.mark.intent
def test_tc07_last_vol_is_last_rolling_value_reported(golden):
    given_input, expected = golden("risk", "TC-07")
    vol = _vol(given_input["vol"])
    want = next(w for w in expected["summary"] if w["ticker"] == "X")

    s = _by_ticker(summary_stats(vol))["X"]

    assert s.last_vol is not None
    assert s.last_vol == pytest.approx(want["last_vol"], abs=expected["tol"])


@pytest.mark.intent
def test_one_ticker_per_input_ticker(contract_sample):
    vol = _vol(contract_sample("risk.VolSeries"))

    got = summary_stats(vol)

    assert [s.ticker for s in got] == list(vol.returns.tickers)


@pytest.mark.intent
@pytest.mark.parametrize("n", [0, 1])
def test_fewer_than_two_returns_is_value_error(contract_sample, n):
    payload = contract_sample("risk.VolSeries")
    returns = payload["returns"]
    short = {
        "returns": {
            **returns,
            "dates": returns["dates"][:n],
            "values": {t: v[:n] for t, v in returns["values"].items()},
        },
        "window": payload["window"],
        "annualized": payload["annualized"],
        "values": {t: v[:n] for t, v in payload["values"].items()},
    }

    with pytest.raises(ValueError, match="two"):
        summary_stats(_vol(short))

